window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-37c6c5fc9b7bc10f"]={"versions": [{"id": "FIG-37c6c5fc9b7bc10f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.</li>\n<li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong></li>\n<li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.</li>\n<li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.</li>\n<li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong></li>\n<li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).</li>\n<li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).</li>\n<li><code>CrsCtlAndAcc</code> (Cruise Control & Adaptive Cruise Control).</li>\n<li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).</li>\n<li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong></li>\n<li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.</li>\n<li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.</li>\n<li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).</li>\n<li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.</li>\n<li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).</li>\n<li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).</li>\n</ul>\n<p class=\"fig-p\">#### Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</p>\n<ul class=\"fig-list\">\n<li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.</li>\n<li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.</li>\n<li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.</li>\n<li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.</li>\n<li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.</li>\n<li><strong>Kardinalitäten:</strong> $1:n$-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); $n:1$-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.</li>\n<li><strong>Kopplungen:</strong></li>\n<li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.</li>\n<li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Erfassung & Vorkonditionierung (Asynchron / Periodisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung > Notausweich-Assistenz > Komfort-Assistenz).</li>\n<li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kinematische Transformation & Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).</li>\n<li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Low-Level-Arbitrierung & Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).</li>\n<li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Ansteuerung & Feedback (Synchrone Reglerschleife):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).</li>\n<li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> $\\rightarrow$ <code>SAC</code> $\\rightarrow$ <code>Esc</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.</li>\n<li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.</li>\n<li><strong>RTE- und Task-Design:</strong></li>\n<li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks ($t_{cycle} = 5\\,\\text{ms} \\dots 10\\,\\text{ms}$).</li>\n<li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung ($t_{cycle} \\le 1\\,\\text{ms} \\dots 2\\,\\text{ms}$), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.</li>\n<li><strong>Signalintegrität & ASIL-Allokation:</strong></li>\n<li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.</li>\n<li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.</li>\n</ul>"}, {"id": "FIG-c73af67f5ddf6043", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.</li>\n<li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong></li>\n<li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.</li>\n<li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.</li>\n<li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong></li>\n<li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).</li>\n<li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).</li>\n<li><code>CrsCtlAndAcc</code> (Cruise Control & Adaptive Cruise Control).</li>\n<li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).</li>\n<li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong></li>\n<li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.</li>\n<li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.</li>\n<li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).</li>\n<li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.</li>\n<li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).</li>\n<li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).</li>\n</ul>\n<p class=\"fig-p\">#### Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</p>\n<ul class=\"fig-list\">\n<li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.</li>\n<li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.</li>\n<li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.</li>\n<li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.</li>\n<li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.</li>\n<li><strong>Kardinalitäten:</strong> $1:n$-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); $n:1$-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.</li>\n<li><strong>Kopplungen:</strong></li>\n<li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.</li>\n<li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Erfassung & Vorkonditionierung (Asynchron / Periodisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung > Notausweich-Assistenz > Komfort-Assistenz).</li>\n<li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kinematische Transformation & Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).</li>\n<li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Low-Level-Arbitrierung & Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).</li>\n<li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Ansteuerung & Feedback (Synchrone Reglerschleife):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).</li>\n<li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> $\\rightarrow$ <code>SAC</code> $\\rightarrow$ <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.</li>\n<li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.</li>\n<li><strong>RTE- und Task-Design:</strong></li>\n<li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks ($t_{cycle} = 5\\,\\text{ms} \\dots 10\\,\\text{ms}$).</li>\n<li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung ($t_{cycle} \\le 1\\,\\text{ms} \\dots 2\\,\\text{ms}$), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.</li>\n<li><strong>Signalintegrität & ASIL-Allokation:</strong></li>\n<li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.</li>\n<li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.</li>\n</ul>"}, {"id": "FIG-628d70dbcd1152a8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.</li>\n<li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong></li>\n<li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.</li>\n<li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.</li>\n<li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong></li>\n<li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).</li>\n<li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).</li>\n<li><code>CrsCtlAndAcc</code> (Cruise Control & Adaptive Cruise Control).</li>\n<li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).</li>\n<li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong></li>\n<li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.</li>\n<li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.</li>\n<li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).</li>\n<li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.</li>\n<li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).</li>\n<li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).</li>\n</ul>\n<p class=\"fig-p\">#### Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</p>\n<ul class=\"fig-list\">\n<li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.</li>\n<li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.</li>\n<li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.</li>\n<li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.</li>\n<li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.</li>\n<li><strong>Kardinalitäten:</strong> $1:n$-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); $n:1$-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.</li>\n<li><strong>Kopplungen:</strong></li>\n<li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.</li>\n<li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Erfassung & Vorkonditionierung (Asynchron / Periodisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung > Notausweich-Assistenz > Komfort-Assistenz).</li>\n<li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kinematische Transformation & Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).</li>\n<li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Low-Level-Arbitrierung & Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).</li>\n<li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Ansteuerung & Feedback (Synchrone Reglerschleife):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).</li>\n<li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> $\\rightarrow$ <code>SAC</code> $\\rightarrow$ <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.</li>\n<li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.</li>\n<li><strong>RTE- und Task-Design:</strong></li>\n<li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks ($t_{cycle} = 5\\,\\text{ms} \\dots 10\\,\\text{ms}$).</li>\n<li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung ($t_{cycle} \\le 1\\,\\text{ms} \\dots 2\\,\\text{ms}$), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.</li>\n<li><strong>Signalintegrität & ASIL-Allokation:</strong></li>\n<li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.</li>\n<li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.</li>\n</ul>"}, {"id": "FIG-ce6167db30a6a08b", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.</li>\n<li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong></li>\n<li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.</li>\n<li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.</li>\n<li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong></li>\n<li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).</li>\n<li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).</li>\n<li><code>CrsCtlAndAcc</code> (Cruise Control & Adaptive Cruise Control).</li>\n<li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).</li>\n<li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong></li>\n<li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.</li>\n<li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.</li>\n<li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).</li>\n<li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.</li>\n<li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).</li>\n<li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).</li>\n</ul>\n<p class=\"fig-p\">#### Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</p>\n<ul class=\"fig-list\">\n<li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.</li>\n<li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.</li>\n<li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.</li>\n<li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.</li>\n<li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.</li>\n<li><strong>Kardinalitäten:</strong> $1:n$-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); $n:1$-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.</li>\n<li><strong>Kopplungen:</strong></li>\n<li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.</li>\n<li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Erfassung & Vorkonditionierung (Asynchron / Periodisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung > Notausweich-Assistenz > Komfort-Assistenz).</li>\n<li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kinematische Transformation & Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).</li>\n<li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Low-Level-Arbitrierung & Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).</li>\n<li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Ansteuerung & Feedback (Synchrone Reglerschleife):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).</li>\n<li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> $\\rightarrow$ <code>SAC</code> $\\rightarrow$ <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.</li>\n<li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.</li>\n<li><strong>RTE- und Task-Design:</strong></li>\n<li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks ($t_{cycle} = 5\\,\\text{ms} \\dots 10\\,\\text{ms}$).</li>\n<li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung ($t_{cycle} \\le 1\\,\\text{ms} \\dots 2\\,\\text{ms}$), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.</li>\n<li><strong>Signalintegrität & ASIL-Allokation:</strong></li>\n<li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.</li>\n<li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.</li>\n</ul>"}, {"id": "FIG-cc1fe776cb87f790", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.</li>\n<li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong></li>\n<li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.</li>\n<li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.</li>\n<li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong></li>\n<li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).</li>\n<li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).</li>\n<li><code>CrsCtlAndAcc</code> (Cruise Control & Adaptive Cruise Control).</li>\n<li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).</li>\n<li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong></li>\n<li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.</li>\n<li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.</li>\n<li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).</li>\n<li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.</li>\n<li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).</li>\n<li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).</li>\n</ul>\n<p class=\"fig-p\">#### Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</p>\n<ul class=\"fig-list\">\n<li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.</li>\n<li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.</li>\n<li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.</li>\n<li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.</li>\n<li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.</li>\n<li><strong>Kardinalitäten:</strong> $1:n$-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); $n:1$-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.</li>\n<li><strong>Kopplungen:</strong></li>\n<li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.</li>\n<li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Erfassung & Vorkonditionierung (Asynchron / Periodisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung > Notausweich-Assistenz > Komfort-Assistenz).</li>\n<li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kinematische Transformation & Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).</li>\n<li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Low-Level-Arbitrierung & Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).</li>\n<li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Ansteuerung & Feedback (Synchrone Reglerschleife):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).</li>\n<li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> $\\rightarrow$ <code>SAC</code> $\\rightarrow$ <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.</li>\n<li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.</li>\n<li><strong>RTE- und Task-Design:</strong></li>\n<li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks ($t_{cycle} = 5\\,\\text{ms} \\dots 10\\,\\text{ms}$).</li>\n<li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung ($t_{cycle} \\le 1\\,\\text{ms} \\dots 2\\,\\text{ms}$), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.</li>\n<li><strong>Signalintegrität & ASIL-Allokation:</strong></li>\n<li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.</li>\n<li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.</li>\n</ul>"}, {"id": "FIG-2f0f777aaed749c6", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.</li>\n<li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong></li>\n<li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.</li>\n<li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.</li>\n<li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong></li>\n<li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).</li>\n<li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).</li>\n<li><code>CrsCtlAndAcc</code> (Cruise Control & Adaptive Cruise Control).</li>\n<li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).</li>\n<li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong></li>\n<li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.</li>\n<li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.</li>\n<li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).</li>\n<li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.</li>\n<li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).</li>\n<li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).</li>\n</ul>\n<p class=\"fig-p\">#### Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</p>\n<ul class=\"fig-list\">\n<li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.</li>\n<li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.</li>\n<li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.</li>\n<li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.</li>\n<li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.</li>\n<li><strong>Kardinalitäten:</strong> $1:n$-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); $n:1$-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.</li>\n<li><strong>Kopplungen:</strong></li>\n<li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.</li>\n<li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Erfassung & Vorkonditionierung (Asynchron / Periodisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung > Notausweich-Assistenz > Komfort-Assistenz).</li>\n<li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kinematische Transformation & Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).</li>\n<li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Low-Level-Arbitrierung & Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).</li>\n<li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Ansteuerung & Feedback (Synchrone Reglerschleife):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).</li>\n<li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> $\\rightarrow$ <code>SAC</code> $\\rightarrow$ <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.</li>\n<li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.</li>\n<li><strong>RTE- und Task-Design:</strong></li>\n<li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks ($t_{cycle} = 5\\,\\text{ms} \\dots 10\\,\\text{ms}$).</li>\n<li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung ($t_{cycle} \\le 1\\,\\text{ms} \\dots 2\\,\\text{ms}$), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.</li>\n<li><strong>Signalintegrität & ASIL-Allokation:</strong></li>\n<li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.</li>\n<li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.</li>\n</ul>"}, {"id": "FIG-8f3cb66c199fc31a", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.</li>\n<li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong></li>\n<li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.</li>\n<li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.</li>\n<li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong></li>\n<li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).</li>\n<li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).</li>\n<li><code>CrsCtlAndAcc</code> (Cruise Control & Adaptive Cruise Control).</li>\n<li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).</li>\n<li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong></li>\n<li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.</li>\n<li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.</li>\n<li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).</li>\n<li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.</li>\n<li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).</li>\n<li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).</li>\n</ul>\n<p class=\"fig-p\">#### Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</p>\n<ul class=\"fig-list\">\n<li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.</li>\n<li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.</li>\n<li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.</li>\n<li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.</li>\n<li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.</li>\n<li><strong>Kardinalitäten:</strong> $1:n$-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); $n:1$-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.</li>\n<li><strong>Kopplungen:</strong></li>\n<li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.</li>\n<li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Erfassung & Vorkonditionierung (Asynchron / Periodisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung > Notausweich-Assistenz > Komfort-Assistenz).</li>\n<li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kinematische Transformation & Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).</li>\n<li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Low-Level-Arbitrierung & Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).</li>\n<li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Ansteuerung & Feedback (Synchrone Reglerschleife):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).</li>\n<li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> $\\rightarrow$ <code>SAC</code> $\\rightarrow$ <code>Esc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.</li>\n<li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.</li>\n<li><strong>RTE- und Task-Design:</strong></li>\n<li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks ($t_{cycle} = 5\\,\\text{ms} \\dots 10\\,\\text{ms}$).</li>\n<li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung ($t_{cycle} \\le 1\\,\\text{ms} \\dots 2\\,\\text{ms}$), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.</li>\n<li><strong>Signalintegrität & ASIL-Allokation:</strong></li>\n<li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.</li>\n<li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.</li>\n</ul>"}], "trans": [{"from": "FIG-37c6c5fc9b7bc10f", "to": "FIG-c73af67f5ddf6043", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bildbeschriftung oben links: Hinzufügen des Textes „Figure 14.“ oberhalb des Legendenkastens.</li>\n</ul>"}, {"from": "FIG-c73af67f5ddf6043", "to": "FIG-628d70dbcd1152a8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-628d70dbcd1152a8", "to": "FIG-ce6167db30a6a08b", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ce6167db30a6a08b", "to": "FIG-cc1fe776cb87f790", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cc1fe776cb87f790", "to": "FIG-2f0f777aaed749c6", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bildbeschriftung oben links: Entfernen des Textes „Figure 14.“ oberhalb des Legendenkastens.</li>\n</ul>"}, {"from": "FIG-2f0f777aaed749c6", "to": "FIG-8f3cb66c199fc31a", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
